sys_script_client.script:
function onSubmit() {

    var modalObj = {};

	var modalMessage = ["By agreeing, you acknowledge that you have read and agree to the terms of the Memorandum of Agreement."];

	//if additional fields need to be removed from the modal
	//add them to the excludeVarsArray
	var excludeVarsArray = ["acknowledgement","formatter2","formatter3","implementation_poc","poc_end","wso_phone_number_container","jem_phone_number_container"];

	var fields = startsWith(g_form.getFieldNames());

	for(i = 0; i < fields.length; i++) {
		var lm = fields[i];
			//if(lm !== "acknowledgement" && lm !== "signer_info" && lm !== "poc_end" && lm !== "formatter2"){
				if(excludeVarsArray.indexOf(lm) === -1){
				modalObj[lm] = {"label":g_form.getLabelOf(lm), "value":g_form.getValue(lm)};
			}
	}

	console.info(modalObj);

    // Check if we are in the Service Portal or Native UI
    if (typeof spModal !== 'undefined') {
		if (g_scratchpad.isFormValid) {
            return true;
        }		

    var table = '<table class="table table-hover table-condensed">' +
				'<tr><h4>' + modalMessage[0] + '</h4></tr>';

	Object.keys(modalObj).forEach(function(key){
		if(key === "implementation_point_of_contact" || key === "public_affairs_point_of_contact"){
			if(key === "implementation_point_of_contact"){
				modalObj[key].label = "Implementation Point of Contact";
			} else if(key === "public_affairs_point_of_contact"){
				modalObj[key].label = "Public Affairs Point of Contact";
			}
			table += '<tr class="ina-287g-poc">' +
			'<th class="tablecell" style="width: auto !important;">' + modalObj[key].label + '</th>'+
			'<td style="border: solid 1px #777;"></td>' +
			'</tr>';
		} else {
			table += '<tr>' +
			'<th class="tablecell" style="width: auto !important">' + modalObj[key].label + '</th>'+
			'<td style="border: solid 1px #777;">' + modalObj[key].value + '</td>' +
			'</tr>';
		}	
	});

    table += "</table>";

    var obj = {
        message: table,
        title: 'Memorandum of Agreement',
        buttons: [{
                label: '✘ Cancel',
                cancel: true
            },
            {
                label: '✔ Agree',
                primary: true
            }
        ]
    };

	var actionName = g_form.getActionName();
    spModal.open(obj).then(function(confirm) {
			g_scratchpad.isFormValid = true;
			g_form.submit(actionName);
			return true;
    });

	g_scratchpad.isFormValid = false;
    return false;
	}

}

function startsWith(vars) {
	var newArr = [];
	var ioVAR = "IO:";
	var inaVar = "ina_";
	var sigVar = "Signatory";
	vars.filter(function(variable){
		var hasIo = (variable.startsWith(ioVAR)) ? true : false;
		var hasIna = (variable.startsWith(inaVar)) ? true : false;
		var hasSig = (variable.startsWith(sigVar)) ? true : false;
		if(!hasIo && !hasIna && !hasSig){
			newArr.push(variable);
		}
	});

	return newArr;
}
